<?php
use App\Core\{Auth, Authorization, Database as DB};
use App\Services\ManagementService as M;
$admin=Authorization::isSuperAdmin();$uid=(int)Auth::user()['id'];
$sp=[];$sw=M::scope('subjects',$sp);$subjects=DB::all("SELECT x.*,(SELECT COUNT(*) FROM student_subjects ss WHERE ss.subject_id=x.id AND ss.status='active') AS students,(SELECT COUNT(*) FROM modules m WHERE m.subject_id=x.id AND m.deleted_at IS NULL) AS modules,COALESCE((SELECT SUM(mp.completion_percent) FROM module_progress mp JOIN student_subjects ss ON ss.student_id=mp.student_id AND ss.subject_id=mp.subject_id AND ss.status='active' WHERE mp.subject_id=x.id)/NULLIF((SELECT COUNT(*) FROM student_subjects ss WHERE ss.subject_id=x.id AND ss.status='active')*(SELECT COUNT(*) FROM modules m WHERE m.subject_id=x.id AND m.status='published' AND m.deleted_at IS NULL),0),0) AS progress FROM subjects x WHERE $sw ORDER BY x.id",$sp);
$up=[];$uw=M::scope('students',$up);$students=(int)DB::val("SELECT COUNT(*) FROM users x WHERE $uw",$up);
$teachers=(int)DB::val("SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE r.code='teacher' AND u.deleted_at IS NULL");
$score=$admin?DB::val('SELECT ROUND(AVG(percentage)) FROM test_attempts WHERE result<>\'pending\''):DB::val("SELECT ROUND(AVG(percentage)) FROM test_attempts WHERE result<>'pending' AND subject_id IN (SELECT subject_id FROM teacher_subjects WHERE teacher_id=?)",[$uid]);
$stats=$admin?[["Total centres",DB::val('SELECT COUNT(*) FROM centres'),'building'],['Total students',$students,'users'],['Total teachers',$teachers,'users'],['Total subjects',count($subjects),'book']]:[['My Subjects',count($subjects),'book'],['Total students',$students,'users'],['Average test score',$score===null?'—':$score.'%','chart'],['Modules',array_sum(array_column($subjects,'modules')),'book']];
$recent=$admin?DB::all("SELECT u.id,u.full_name,u.username,u.status,u.created_at,r.name AS role,c.name AS centre FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN centres c ON c.id=u.centre_id WHERE u.deleted_at IS NULL ORDER BY u.created_at DESC,u.id DESC LIMIT 6"):DB::all("SELECT x.id,x.full_name,x.username,x.status,x.created_at,'Student' AS role,c.name AS centre FROM users x LEFT JOIN centres c ON c.id=x.centre_id WHERE $uw ORDER BY x.created_at DESC,x.id DESC LIMIT 6",$up);
if(!$admin&&!Authorization::can('students.view')){$recent=[];}
$monthly=$admin?DB::all("SELECT DATE_FORMAT(enrolled_at,'%Y-%m') AS month,COUNT(*) AS total FROM student_subjects WHERE enrolled_at>=DATE_FORMAT(DATE_SUB(CURDATE(),INTERVAL 5 MONTH),'%Y-%m-01') GROUP BY month"):DB::all("SELECT DATE_FORMAT(enrolled_at,'%Y-%m') AS month,COUNT(*) AS total FROM student_subjects WHERE enrolled_at>=DATE_FORMAT(DATE_SUB(CURDATE(),INTERVAL 5 MONTH),'%Y-%m-01') AND subject_id IN (SELECT subject_id FROM teacher_subjects WHERE teacher_id=?) GROUP BY month",[$uid]);
$monthMap=array_column($monthly,'total','month');$max=max([1,...array_values($monthMap)]);
page_header('Dashboard');
?>
<section class="intro"><h2><?= e(tr('Welcome back')) ?>, <?= e($admin?'Admin':explode(' ',preg_replace('/^Demo /','',Auth::user()['name']))[0]) ?> <span aria-hidden="true">👋</span></h2><p><?= e(tr($admin?'Manage your training centres, people and learning content.':'Keep learning, keep growing.')) ?></p></section>
<div class="stats-grid"><?php foreach($stats as [$label,$value,$ico]): ?><div class="stat-card"><span class="stat-symbol"><?= icon($ico) ?></span><div><div class="stat-label"><?= e(tr($label)) ?></div><div class="stat-number"><?= e((string)$value) ?></div></div></div><?php endforeach; ?></div>
<?php if(!$admin): ?><section class="card"><div class="card-heading"><h2><?= e(tr('My Subjects')) ?></h2><a href="subjects.php"><?= e(tr('View all')) ?> →</a></div><div class="course-grid"><?php foreach($subjects as $s): ?><article class="course-card"><div class="course-visual"><?= icon($s['code']==='ELEC'?'bolt':'book') ?></div><div class="course-body"><h3><?= e($s['name']) ?></h3><small><?= $s['students'] ?> <?= e(tr('Students')) ?> · <?= $s['modules'] ?> <?= e(tr('Modules')) ?></small><div class="progress-track"><div class="progress-fill w<?= (int)min(100,(float)$s['progress']) ?>"></div></div><a class="btn" href="students.php?subject_id=<?= (int)$s['id'] ?>"><?= e(tr('View students')) ?> <?= icon('arrow') ?></a></div></article><?php endforeach; ?><?php if(!$subjects): ?><p><?= e(tr('No subjects assigned yet.')) ?></p><?php endif; ?></div></section><?php endif; ?>
<div class="dashboard-columns"><section class="card"><div class="card-heading"><h2><?= e(tr('Student enrolment')) ?></h2><span class="pill"><?= e(tr('Last six months')) ?></span></div><div class="chart-bars" role="img" aria-label="<?= e(tr('Student enrolment')) ?>"><?php for($i=5;$i>=0;$i--): $date=(new DateTimeImmutable('first day of this month'))->modify("-$i months");$count=(int)($monthMap[$date->format('Y-m')]??0); ?><div class="chart-col"><strong><?= $count ?></strong><div class="bar h<?= (int)max(2,($count/$max)*85) ?>"></div><small><?= e(tr($date->format('M'))) ?></small></div><?php endfor; ?></div><small class="muted"><?= e(tr('Data is calculated from saved records.')) ?></small></section>
<section class="card"><div class="card-heading"><h2><?= e(tr('Subject-wise progress')) ?></h2><a href="reports.php"><?= e(tr('Reports')) ?> →</a></div><?php foreach($subjects as $s): $percent=min(100,max(0,round((float)$s['progress']))); ?><div class="progress-row"><div><?= e($s['name']) ?><div class="progress-track"><div class="progress-fill w<?= (int)$percent ?>"></div></div></div><b><?= $percent ?>%</b></div><?php endforeach; ?></section></div>
<div class="dashboard-lower"><section class="card"><div class="card-heading"><h2><?= e(tr('Recent users')) ?></h2><a href="<?= $admin?'users':'students' ?>.php"><?= e(tr('View all')) ?> →</a></div><div class="table-wrap"><table><thead><tr><?php foreach(['Name','Role','Centre','Status','Joined'] as $label): ?><th><?= e(tr($label)) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><div class="name-cell"><span class="avatar"><?= e(mb_substr($r['full_name'],0,1)) ?></span><strong><?= e($r['full_name']) ?></strong></div></td><td><?= e(tr($r['role'])) ?></td><td><?= e($r['centre']??'—') ?></td><td><span class="pill <?= e($r['status']) ?>"><?= e(tr($r['status'])) ?></span></td><td><?= e(fmt_date($r['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card"><h2><?= e(tr($admin?'System status':'Quick actions')) ?></h2><?php if($admin): ?><?php foreach([['Database','Online','building'],['Local file storage',is_writable(APP_ROOT.'/storage')?'Online':'Not configured','book'],['Session storage',ini_get('session.save_handler')==='redis'?'Redis':'Local sessions','lock']] as [$label,$value,$ico]): ?><div class="status-row"><span><?= icon($ico) ?><?= e(tr($label)) ?></span><span><i class="status-dot"></i><?= e(tr($value)) ?></span></div><?php endforeach; ?><?php endif; ?><div class="quick-links spaced"><a class="btn" href="modules.php"><?= icon('book') ?><?= e(tr('Content')) ?></a><a class="btn" href="tests.php"><?= icon('test') ?><?= e(tr('Tests')) ?></a><a class="btn" href="attendance.php"><?= icon('check') ?><?= e(tr('Attendance')) ?></a></div></section></div>
<?php page_footer();
